using UnityEngine;\nusing System;\n\n/// <summary>\nManages knockback and hit reaction physics.\n/// </summary>\npublic class KnockbackSystem : MonoBehaviour\n{\n    [SerializeField] private float knockbackMultiplier = 1f;\n    [SerializeField] private float maxKnockbackForce = 20f;\n    \n    public Vector3 CalculateKnockback(\n        Vector3 direction,\n        float force,\n        float defenderDefense)\n    {\n        // Direction is normalized from attacker to defender\n        Vector3 knockback = direction.normalized * force;\n        \n        // Apply defender defense as resistance (0-50% reduction)\n        float resistance = 1f - (defenderDefense / 200f);\n        knockback *= resistance * knockbackMultiplier;\n        \n        // Cap maximum knockback\n        if (knockback.magnitude > maxKnockbackForce)\n        {\n            knockback = knockback.normalized * maxKnockbackForce;\n        }\n        \n        return knockback;\n    }\n    \n    public void ApplyKnockback(Rigidbody target, Vector3 knockback)\n    {\n        if (target == null)\n            return;\n        \n        // Don't override Y velocity if falling\n        if (knockback.y < 0 && target.velocity.y < 0)\n        {\n            knockback.y = 0;\n        }\n        \n        target.velocity = knockback;\n    }\n    \n    public void ApplyAirLaunch(Rigidbody target, float launchForce = 10f)\n    {\n        if (target == null)\n            return;\n        \n        target.velocity = new Vector3(target.velocity.x, launchForce, target.velocity.z);\n    }\n}\n"